import{_ as t,o as a,c as s,ae as l}from"./chunks/framework.EHGTsUvI.js";const u=JSON.parse('{"title":"Pallet Storage","description":"","frontmatter":{"title":"Pallet Storage"},"headers":[],"relativePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Utilities/palletstorage.md","filePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Utilities/palletstorage.md"}'),n={name:"Main/Main/GeneralKnowledge/Factorys&Utilities/Utilities/palletstorage.md"};function i(o,e,r,p,d,h){return a(),s("div",null,[...e[0]||(e[0]=[l(`<h1 id="pallet-storage" tabindex="-1">Pallet Storage <a class="header-anchor" href="#pallet-storage" aria-label="Permalink to &quot;Pallet Storage&quot;">​</a></h1><p>Pallet Storage is a building used to store and organise pallets. It can separate different products from the same pallet while keeping identical products together.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Pallet Storage is used to:</p><ul><li>Store pallets</li><li>Sort mixed pallets</li><li>Separate different products onto their own pallets</li><li>Keep identical products together</li><li>Create empty pallets</li></ul><h2 id="how-to-use" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to Use&quot;">​</a></h2><h3 id="_1-place-a-pallet-into-storage" tabindex="-1">1. Place a Pallet Into Storage <a class="header-anchor" href="#_1-place-a-pallet-into-storage" aria-label="Permalink to &quot;1. Place a Pallet Into Storage&quot;">​</a></h3><p>Use a <strong>Forklift</strong> to place a pallet into the Pallet Storage building.</p><p>The pallet can contain one or multiple types of products.</p><h3 id="_2-store-the-pallet" tabindex="-1">2. Store the Pallet <a class="header-anchor" href="#_2-store-the-pallet" aria-label="Permalink to &quot;2. Store the Pallet&quot;">​</a></h3><p>Once deposited, Pallet Storage sorts the contents based on the product type.</p><p>Different products are separated onto their own pallets, while identical products remain together.</p><h3 id="_3-withdraw-the-products" tabindex="-1">3. Withdraw the Products <a class="header-anchor" href="#_3-withdraw-the-products" aria-label="Permalink to &quot;3. Withdraw the Products&quot;">​</a></h3><p>Use the forklift to remove the stored pallets.</p><p>Different products that were originally on the same pallet will now be on separate pallets.</p><p>For example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Input:</span></span>
<span class="line"><span>1 Pallet</span></span>
<span class="line"><span>├── 5 Wheat Seeds</span></span>
<span class="line"><span>└── 5 Corn Seeds</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Output:</span></span>
<span class="line"><span>├── Wheat Seed Pallet</span></span>
<span class="line"><span>│   └── 5 Wheat Seeds</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└── Corn Seed Pallet</span></span>
<span class="line"><span>    └── 5 Corn Seeds</span></span></code></pre></div><p>Identical products remain together:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Input:</span></span>
<span class="line"><span>1 Pallet</span></span>
<span class="line"><span>└── 2 Wheat Seeds</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Output:</span></span>
<span class="line"><span>└── Wheat Seed Pallet</span></span>
<span class="line"><span>    └── 2 Wheat Seeds</span></span></code></pre></div><p>Pallet Storage <strong>does not split identical products into separate pallets</strong>.</p><h2 id="cost" tabindex="-1">Cost <a class="header-anchor" href="#cost" aria-label="Permalink to &quot;Cost&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Information</th><th>Details</th></tr></thead><tbody><tr><td>Purchase Price</td><td>120,000 Coins</td></tr><tr><td>Input</td><td>Pallets</td></tr><tr><td>Output</td><td>Sorted Pallets</td></tr><tr><td>Building Size</td><td>14 × 13</td></tr></tbody></table><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li><strong>Forklift License</strong></li><li><strong>Forklift</strong></li><li><strong>120,000 Coins</strong></li><li>Pallets to store</li></ul><h2 id="useful-information-tips" tabindex="-1">Useful Information &amp; Tips <a class="header-anchor" href="#useful-information-tips" aria-label="Permalink to &quot;Useful Information &amp; Tips&quot;">​</a></h2><ul><li>Different products on the same pallet are separated when withdrawn.</li><li>Identical products remain together on the same pallet.</li><li>The number of items is not changed when storing them.</li><li>Mixed seed pallets can be separated into individual seed pallets.</li><li>This is useful for organising pallets containing multiple products.</li><li>Empty pallets can be obtained by removing all products from a stored pallet.</li><li>Pallet Storage is especially useful when dealing with large quantities of seeds or factory-produced products.</li></ul><blockquote><p><strong>Example:</strong> If a pallet contains <strong>2 Wheat Seeds</strong>, they will come back out as <strong>2 Wheat Seeds on one pallet</strong>, rather than two separate pallets.</p></blockquote>`,27)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
